    packages = data.get('packages', {})
    roots = data.get('roots', {})
    names = sorted(packages)
    features = set(data.get('features', []))
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})

    domains = {
        name: list(packages[name])
        for name in names
    }
    constraints = {name: [tuple(bounds)] for name, bounds in roots.items()}
    if any(name not in packages for name in roots):
        return {'error': 'unsatisfiable'}

    best_assignment = None
    best_vector = None
    assignment = {}

    def active_deps(row):
        for dep in row.get('deps', []):
            feature = dep.get('feature')
            if feature and feature not in features:
                continue
            yield dep

    def acyclic(edges):
        state = {}

        def visit(node):
            mark = state.get(node, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[node] = 1
            for target in edges.get(node, ()):
                if not visit(target):
                    return False
            state[node] = 2
            return True

        return all(visit(node) for node in edges)

    def allowed(name, version, limits):
        if version in blocked.get(name, []):
            return False
        if name in pins and version != pins[name]:
            return False
        return all(lo <= version <= hi for lo, hi in limits)

    def search(i, limits, edges):
