        # The absent choice has objective value -1.
        options.append((-1, None))
        options.sort(key=lambda item: item[0], reverse=True)

        for _, row in options:
            if row is None:
                if limits.get(name):
                    continue
                assignment[name] = None
                search(i + 1, limits, edges)
                del assignment[name]
                continue

            version = row['version']
            if not allowed(name, version, limits.get(name, ())):
                continue
            new_limits = {n: list(ranges) for n, ranges in limits.items()}
            new_edges = {n: list(targets) for n, targets in edges.items()}
            deps = list(active_deps(row))
            valid = True
            for dep in deps:
                target = dep['name']
                if target not in packages:
                    valid = False
                    break
                bounds = (dep['min'], dep['max'])
                new_limits.setdefault(target, []).append(bounds)
