                    chosen = assignment[target]
                    if chosen is None or not allowed(target, chosen, new_limits[target]):
                        valid = False
                        break
                new_edges.setdefault(name, []).append(target)
            if not valid or not acyclic(new_edges):
                continue

            assignment[name] = version
            search(i + 1, new_limits, new_edges)
            del assignment[name]

    search(0, constraints, {})
    if best_assignment is None:
